from pathlib import Path
import json
D=Path(__file__).resolve().parent
def f(x,n=2):return f'{x:,.{n}f}'.replace(',',' ').replace('.',',')
def fmt(z):return f"{f(100*z['advantage'])}% [{f(100*z['ci'][0])}%; {f(100*z['ci'][1])}%]"
def get(k):return json.loads((D/k).read_bytes())
def main():
    r=get('results.json');cost=get('heap.json');tot=r['totals'];q=r['quality'];cs=r['comparisons']
    names={'proposed':'Частота × стоимость','s3':'S3-FIFO, пакет со стоимостным порядком','sieve':'SIEVE, пакет со стоимостным порядком'}
    a=cs['s3']['wall_rank'];b=cs['sieve']['wall_rank']
    passed=a['ci'][0]>0 and b['ci'][0]>0
    verdict='Критерий ускорения относительно обоих контролей выполнен.' if passed else 'Критерий ускорения относительно обоих контролей не выполнен.'
    out=['# Задержка выдачи при сравнении с S3-FIFO и SIEVE',
      f"**{verdict}** При равной ёмкости 31 вектор и расчётном бюджете 512 КиБ разница сквозного времени относительно S3-FIFO составила **{fmt(a)}**, относительно SIEVE — **{fmt(b)}**. Положительный знак обозначает экономию времени. В отдельных цепочках преимущество наблюдалось на {a['wins']}/8 и {b['wins']}/8 репозиториев соответственно. Приведены индивидуальные 95% интервалы парного бутстрепа по репозиториям. [Предварительный протокол](PROTOCOL_RU.md) · [Сводные результаты](results.json)",
      "Один сеанс Qwen3-Embedding-8B Q4_K_M на RTX 3090 обслужил все три режима. Испытано 24 состояния из восьми ранее отобранных репозиториев, по три последовательных снимка одного запуска. Каждый режим начинал с пустым постоянным кешем. Сначала все кандидаты текущего запроса проверялись относительно одного снимка резидентов. При последующей записи S3-FIFO и SIEVE получали тот же заранее проверенный порядок с приоритетом дорогих источников. Расходы в токенах на этих состояниях и результаты прежнего опыта с другими политиками были известны. [Адаптеры, сравненные с оригинальной реализацией](../cache_controls/REPORT_RU.md)",
      '## Физические величины']
    tab=['| Алгоритм | Время до выдачи, с | С записью, с | CUDA engine, с | Вызовы эмбеддинга, с | Новые входные токены | Хиты в кеше | MSS@5 / MSS@8, из 24 |',
         '|---|---:|---:|---:|---:|---:|---:|---:|']
    for m in names:
        rec=tot[m];qa=q[m]
        tab.append(f"| {names[m]} | {f(rec['wall_rank'])} | {f(rec['wall_commit'])} | {f(rec['compute_engine_s'])} | {f(rec['rpc_wall'])} | {f(rec['tokens'],0)} | {f(rec['hit'],0)} | {int(qa['mss5'])} / {int(qa['mss8'])} |")
    out+=['\n'.join(tab),f"Время измерялось от исходных текстовых полей, включая локальную токенизацию каждого входа, вычисление ключей, чтение прежних векторов, реальный вызов GPU, вычисление сходства и сортировку. Время до завершения обновления постоянных объектов приведено в столбце «С записью». Отдельные приращения активности CUDA-движков процесса кодировщика дали {fmt(cs['s3']['compute_engine_s'])} относительно S3-FIFO и {fmt(cs['sieve']['compute_engine_s'])} относительно SIEVE. [Квитанции запросов](receipts.json.gz)",
      f"Относительная экономия входных токенов на аппаратной подвыборке составила {fmt(cs['s3']['tokens'])} и {fmt(cs['sieve']['tokens'])}. Во всех 72 измерениях число документов, найденных в кеше, и число входных токенов совпали с предварительным CPU-расчётом. Выигрыш на 179 состояниях предыдущего исследования выражен в процентных пунктах общего исходного входа. Для аппаратной подвыборки знаменатель — расход сравниваемого алгоритма. [Исходные аппаратные цепочки](../long_gpu/panel.json)",
      '## Парные измерения по репозиториям']
    tab=['| Репозиторий | Частота × стоимость, с | S3-FIFO, с | SIEVE, с |','|---|---:|---:|---:|']
    for name in r['repos']:
        gr=r['groups'][name]
        tab.append(f"| {name} | {f(gr['proposed']['wall_rank'])} | {f(gr['s3']['wall_rank'])} | {f(gr['sieve']['wall_rank'])} |")
    allv=sum(z['vector_matches'] for z in q.values());need=sum(z['n_vectors'] for z in q.values());rank=sum(z['rank_equal'] for z in q.values());err=max(z['max_score_error'] for z in q.values())
    exceeding=sum(n>cost['limit'] for v in cost['sizes'].values() for n in v['s3'])
    extra=max(0,cost['max_bytes']['s3']-cost['limit'])
    out+=['\n'.join(tab),f"В сравнении с сохранённым полным прямым вычислением совпало {f(allv,0)} из {f(need,0)} проверенных векторов во всех трёх режимах и {rank}/72 полных ранжирований. Наибольшее абсолютное различие косинусных оценок {err:.3g}. Время исторического эталона не входит ни в один контраст. [Подробная проверка качества](quality.json.gz)",
      f"Пиковый объём удерживаемых после записи объектов Python, реконструированный по фактическим ключам, составил {f(cost['max_bytes']['proposed'],0)} байт для исследуемой политики, {f(cost['max_bytes']['s3'],0)} для S3-FIFO и {f(cost['max_bytes']['sieve'],0)} для SIEVE при бюджете сохранённых данных 524 288 байт. У Python-адаптера S3-FIFO размер выше 512 КиБ в {exceeding} из 24 состояний, максимум на {f(extra,0)} байт. Поэтому сопоставление фиксирует одинаковые 31 слот для векторов. Логическая упаковка метаданных всех трёх политик укладывается в предел (максимум 511 224 байта). Утверждение о строгом равенстве физически выделенной памяти Python здесь не поддержано. Рабочие буферы текущего запроса и общая модель находятся за пределами этого бюджета. [Аудит удерживаемых объектов](heap.json)",
      "Число независимых единиц сравнения — восемь репозиториев. Перестановки режимов уравновешены по порядку, каждый вариант на конкретной цепочке измерен однократно. Межрепозиторный интервал не отражает повторные разгоны GPU, междневную вариативность, другие модели или платформы. Результаты относятся к трёхшаговым архивным запросам и зафиксированным Python-интеграциям. Опыт оценивает стоимость чтения памяти с одинаковыми входами. [Воспроизведение](REPRODUCE_RU.md) · [Подпись серверного сеанса](seal.json)"]
    (D/'REPORT_RU.md').write_text('\n\n'.join(out)+'\n',encoding='utf-8')
if __name__=='__main__':main()

